ruleContent.content:
@js:
(function(){
  // result 是 ruleToc 里 chapterUrl 请求的响应, 或直接返回 URL
  var u = result || '';
  if (u && u.indexOf('http') === 0) return u;
  try {
    var d = JSON.parse(result);
    if (d && d.data) {
      var su = d.data.streamURL || [];
      for (var i=0;i<su.length;i++){
        if (su[i].status === 1 && !su[i].onlyVIP && su[i].stream) return su[i].stream;
      }
      if (su.length) return su[0].stream;
    }
  }catch(e){}
  return '';
})()

ruleExplore.author:
@js:
(function(){
  if (result.artistName) return result.artistName;
  if (result.artist && result.artist.length) return result.artist[0].name;
  return '';
})()

ruleExplore.bookList:
@js:
(function(){
  // charts: data[]; recommend: data.list[]
  var d = JSON.parse(result);
  var arr = d.data || [];
  if (d.data && d.data.list) arr = d.data.list;
  return arr;
})()

ruleExplore.bookUrl:
@js:
(function(){
  var k = result.key || result.playlistKey || '';
  // 榜单key(charts)用 charts/{key} 接口; 普通歌单用 playlist/detail/{key}
  var t = result.tag || result.category || '';
  if (t === 'TRENDING_MUSIC' || (result.titleDetail && result.items)) {
    return 'https://graph.nct.vn/api/v1/playlist/charts/' + k;
  }
  return 'https://graph.nct.vn/api/v1/playlist/detail/' + k;
})()

ruleExplore.intro:
@js:
(function(){
  var t = result.title || result.titleDetail || result.name || '';
  var n = result.items ? result.items.length : '';
  return t + (n ? ' | ' + n + '首' : '');
})()

ruleExplore.note:
@js:
(function(){
  var n = result.items ? result.items.length : '';
  return n ? n + '首·连播' : '';
})()

ruleSearch.note:
@js:
(function(){
  var d = result.duration || 0;
  var m = Math.floor(d/60), s = d%60;
  return m + ':' + (s<10?'0':'') + s;
})()

ruleToc.chapterList:
@js:
(function(){
  try{ book.type = 32; }catch(e){}
  var out = [];
  var j = null;
  try { j = JSON.parse(result); } catch(e){}
  if (!j || !j.data) return out;
  var list = j.data.listSong || [];
  if (!list.length && j.data.items) list = j.data.items;
  var n = j.data.name || j.data.title || '';
  var seen = {};
  for (var i=0;i<list.length;i++){
    var it = list[i] || {};
    var k = it.key || '';
    if (!k || seen[k]) continue;
    seen[k] = 1;
    var nm = it.name || ('Track ' + (i+1));
    var ar = it.artistName || (it.artist && it.artist.length ? it.artist[0].name : '');
    // 章节URL = 歌曲详情接口(ruleContent里再解析streamURL)
    var u = 'https://graph.nct.vn/api/v1/song/detail/' + k;
    out.push({
      name: (i+1) + '. ' + nm + (ar ? ' - ' + ar : ''),
      url: u
    });
  }
  return out;
})()
